import{_ as a,c as o,o as i,aj as t}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Privacy Policy","description":"Privacy Policy for KitchenRatio","frontmatter":{"title":"Privacy Policy","description":"Privacy Policy for KitchenRatio"},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md"}'),r={name:"privacy-policy.md"};function n(c,e,l,s,h,d){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p>Last updated: February 20, 2026</p><p>KitchenRatio (&quot;we&quot;, &quot;us&quot;, &quot;our&quot;) respects your privacy. This page explains what data we collect, why we collect it, and your choices.</p><h2 id="information-we-collect" tabindex="-1">Information We Collect <a class="header-anchor" href="#information-we-collect" aria-label="Permalink to “Information We Collect”">​</a></h2><ul><li>Usage data: We use Google Analytics to understand general site usage, such as page views, approximate location, device type, and referrer data.</li><li>Tip checkout data: If you choose to leave a tip, checkout is handled by a third-party payment processor. We do not store your full payment card details on KitchenRatio.</li><li>Contact data: If you contact us directly, we may receive the information you include in your message.</li></ul><h2 id="how-we-use-information" tabindex="-1">How We Use Information <a class="header-anchor" href="#how-we-use-information" aria-label="Permalink to “How We Use Information”">​</a></h2><ul><li>To operate and improve KitchenRatio.</li><li>To measure content performance and site reliability.</li><li>To process optional tip payments through our payment provider.</li><li>To detect abuse and maintain service security.</li></ul><h2 id="cookies-and-tracking" tabindex="-1">Cookies and Tracking <a class="header-anchor" href="#cookies-and-tracking" aria-label="Permalink to “Cookies and Tracking”">​</a></h2><p>We use a consent banner for analytics cookies. Analytics tracking is enabled only after you accept. You can change your preference using the &quot;Cookie Preferences&quot; control in the footer.</p><p>See <code>/cookie-policy</code> for more details.</p><h2 id="sharing" tabindex="-1">Sharing <a class="header-anchor" href="#sharing" aria-label="Permalink to “Sharing”">​</a></h2><p>We may share limited data with service providers that help operate the site, such as analytics and payment providers. We do not sell personal information.</p><h2 id="data-retention" tabindex="-1">Data Retention <a class="header-anchor" href="#data-retention" aria-label="Permalink to “Data Retention”">​</a></h2><p>We retain data only as long as needed for the purposes described above, unless a longer period is required by law.</p><h2 id="your-choices" tabindex="-1">Your Choices <a class="header-anchor" href="#your-choices" aria-label="Permalink to “Your Choices”">​</a></h2><ul><li>Decline analytics cookies from the banner.</li><li>Reopen cookie settings from the footer.</li><li>Use browser controls to clear stored cookies.</li></ul><h2 id="children" tabindex="-1">Children <a class="header-anchor" href="#children" aria-label="Permalink to “Children”">​</a></h2><p>KitchenRatio is not intended for children under 13.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to “Changes to This Policy”">​</a></h2><p>We may update this policy over time. The &quot;Last updated&quot; date reflects the current version.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>Questions about privacy can be sent at <code>ckohl.com/contact</code>.</p>',22)])])}const y=a(r,[["render",n]]);export{u as __pageData,y as default};
